export interface SortByUp01IconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface SortByUp01IconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

// the direction arrow rises as the two values trade visual emphasis
